function organicPine(name,x,y,s){
 const result={};
 for(let i=0;i<3;i++){
  const top=y-70*s+i*29*s,w=(24+i*6)*s,bottom=y-14*s+i*29*s;
  result[`${name}枝叶${i+1}`]=`M${x} ${top}Q${x-5*s} ${top+24*s} ${x-w} ${bottom-5*s}Q${x-12*s} ${bottom+2*s} ${x} ${bottom-2*s}Q${x+14*s} ${bottom+3*s} ${x+w} ${bottom-5*s}Q${x+6*s} ${top+24*s} ${x} ${top}Z`;
 }
 return result;
}
