export function refineBoard(source){
 const replacements=paths[source.id]||{};
 let regions=source.regions.map(region=>replacements[region.name]?{...contour(region.name,replacements[region.name]),id:region.id}:{...region,attrs:{...region.attrs}});
 if(source.id==='valley-falls'){
  const pool=regions.find(r=>r.name==='水潭');Object.assign(pool,contour(pool.name,'M91 348Q131 328 194 342Q231 334 279 338C316 332 378 343 397 362Q430 395 348 415C286 440 177 429 116 407Q65 391 78 369Q80 355 91 348Z'));
  const splash=regions.find(r=>r.name==='落水浪花');Object.assign(splash,contour(splash.name,'M191 352Q184 346 193 341Q200 335 212 343Q220 330 232 341Q244 331 253 341Q265 333 274 343Q291 337 295 349Q288 364 242 366Q207 368 191 352Z'));
 }
 if(source.id==='sunset-cove'){
  // Bark bands follow the curved trunk instead of protruding like a ladder.
  for(let i=0;i<4;i++){
   const y=225+i*34,left=[104,104,99,89][i],right=[119,123,119,110][i];
   const region=regions.find(r=>r.name===`树干纹理${i+1}`);
   Object.assign(region,contour(region.name,`M${left} ${y}Q${(left+right)/2} ${y+4} ${right} ${y-2}L${right} ${y+8}Q${(left+right)/2} ${y+15} ${left-2} ${y+10}Z`));
  }
 }
 if(source.id==='greenhouse'){
  // Arched roof panes align with the curved outer roof rather than straight spokes.
  for(let i=0;i<4;i++){
   const region=regions.find(r=>r.name===`屋顶玻璃${i+1}`),x=60+i*89;
   Object.assign(region,contour(region.name,`M${x} 151Q${(x+240)/2} ${[93,76,76,93][i]} 240 50Q${(x+89+240)/2} ${[82,72,82,108][i]} ${x+89} 151Z`));
  }
 }
 // Botanical petals taper toward their center instead of overlapping circles.
 for(const region of regions){
  const petal=region.name.match(/^(.*)花瓣([1-5])$/);
  if(!petal||region.tag!=='ellipse')continue;
  const center=regions.find(r=>r.name===petal[1]+'花心');if(!center||center.tag!=='ellipse')continue;
  const x=center.attrs.cx,y=center.attrs.cy,scale=center.attrs.rx/15,a=(Number(petal[2])-1)*Math.PI*2/5;
  const point=(radial,side)=>[x+Math.sin(a)*radial*scale+Math.cos(a)*side*scale,y-Math.cos(a)*radial*scale+Math.sin(a)*side*scale].map(v=>v.toFixed(2)).join(' ');
  Object.assign(region,contour(region.name,`M${point(5,0)}C${point(14,-23)} ${point(42,-20)} ${point(43,0)}C${point(42,20)} ${point(14,23)} ${point(5,0)}Z`));
 }
 if(source.id==='woodland-tea'){
  for(const [i,x]of [[0,56],[1,429]]){
   const crown=regions.find(r=>r.name===`树冠${i}`),lower=regions.find(r=>r.name===`树冠下层${i}`);
   Object.assign(crown,contour(crown.name,`M${x-33} 136C${x-55} 125 ${x-45} 101 ${x-34} 94C${x-41} 75 ${x-26} 57 ${x-13} 58C${x-10} 35 ${x+14} 34 ${x+23} 53C${x+43} 50 ${x+51} 75 ${x+39} 89C${x+57} 113 ${x+42} 144 ${x+24} 145Q${x} 164 ${x-33} 136Z`));
   Object.assign(lower,contour(lower.name,`M${x-27} 198C${x-47} 187 ${x-40} 168 ${x-30} 160C${x-36} 141 ${x-14} 129 ${x} 143C${x+16} 126 ${x+38} 140 ${x+31} 157C${x+49} 172 ${x+38} 200 ${x+22} 200Q${x} 219 ${x-27} 198Z`));
  }
 }
 if(source.id==='bakery'){
  for(let i=0;i<3;i++){
   const x=119+i*67,region=regions.find(r=>r.name===`上层圆面包${i}`);
   Object.assign(region,contour(region.name,`M${x-25} 230C${x-29} 214 ${x-14} 205 ${x} 208C${x+17} 204 ${x+29} 216 ${x+24} 232Q${x+8} 246 ${x-15} 240Q${x-23} 238 ${x-25} 230Z`));
  }
 }
 let ink=source.ink;

 // Fine botanical veins and pottery marks add detail without tiny mandatory cells.
 for(const region of regions){
  if(region.tag==='ellipse'&&/珍珠|珠子/.test(region.name)){
   const {cx,cy,rx,ry}=region.attrs;ink+=engraving(`M${cx-rx*.48} ${cy}Q${cx-rx*.52} ${cy-ry*.6} ${cx} ${cy-ry*.63}`);
  }
 }
 if(source.id==='greenhouse'){
  for(const [x,y,s]of [[91,283,.65],[145,283,.65],[330,283,.65],[387,283,.65],[95,394,1],[383,391,1]])ink+=engraving(`M${x} ${y-2*s}L${x+5*s} ${y-28*s}M${x} ${y-7*s}L${x+20*s} ${y-27*s}M${x-12*s} ${y+11*s}L${x-10*s} ${y+23*s}M${x+12*s} ${y+11*s}L${x+10*s} ${y+23*s}`);
 }
 if(source.id==='moon-jewels'){
  ink+=engraving('M127 142C121 228 166 301 223 296M353 142C359 228 314 301 257 296M120 171Q103 166 105 179Q105 191 123 189M116 201Q98 200 104 214Q109 224 122 220M126 233Q107 237 119 248Q131 256 137 249M145 261Q131 275 147 279Q163 278 159 272M168 281Q163 299 180 297Q192 292 181 287M360 171Q377 166 375 179Q375 191 357 189M364 201Q382 200 376 214Q371 224 358 220M354 233Q373 237 361 248Q349 256 343 249M335 261Q349 275 333 279Q317 278 321 272M312 281Q317 299 300 297Q288 292 299 287M62 318Q68 328 75 318M403 318Q410 328 417 318');
 }
 if(source.id==='flower-tiara')ink+=engraving('M84 221Q85 250 101 264Q111 255 100 250Q89 248 91 238M396 221Q395 250 379 264Q369 255 380 250Q391 248 389 238M175 216Q183 227 191 222Q202 215 195 207M305 216Q297 227 289 222Q278 215 285 207M227 190Q216 198 224 208M253 190Q264 198 256 208M126 401Q118 416 113 415M166 401Q174 416 179 415');
 if(source.id==='greenhouse')ink+=engraving('M116 156Q105 133 93 146Q93 157 107 150M110 135Q126 123 129 136Q127 143 114 140M364 156Q375 133 387 146Q387 157 373 150M370 135Q354 123 351 136Q353 143 366 140M79 185V203M115 185V197M151 185V204M309 185V204M345 185V197M381 185V204');
 if(source.id==='woodland-tea')ink+=engraving('M56 145V169M56 158L41 147M56 153L70 140M429 145V169M429 158L414 147M429 153L443 140M45 173Q55 181 65 174M418 173Q428 181 438 174');
 return {...source,regions,ink:ink+engraving(details[source.id]||''),lineScale:.72};
}
